(()=>{function bindUpload(id,previewId){const f=document.getElementById(id),box=document.getElementById(previewId),img=box.querySelector("img");f.onchange=()=>{const x=f.files[0];if(!x)return;if(x.size>5*1024*1024){alert("图片大小不能超过5M");f.value="";return}img.src=URL.createObjectURL(x);box.hidden=false}}bindUpload("labReport","labPreview");bindUpload("ecgReport","ecgPreview");const form=document.getElementById("examForm");
/* 条件输入：.value[data-when="name=值"] 仅在对应单选选中时显示；“未查”勾选后禁用并清空同一 [data-nc-scope] 内的其他输入 */
function sync(){form.querySelectorAll("[data-nc-scope] input").forEach(x=>{if(!x.closest(".nc"))x.disabled=false});form.querySelectorAll(".value[data-when]").forEach(v=>{const [n,val]=v.dataset.when.split("="),on=!!form.querySelector(`input[name="${n}"][value="${val}"]:checked`),inp=v.querySelector("input");v.classList.toggle("is-hidden",!on);inp.disabled=!on;if(!on)inp.value=""});form.querySelectorAll(".nc input").forEach(c=>{const scope=c.closest("[data-nc-scope]");c.parentElement.classList.toggle("is-on",c.checked);if(!c.checked)return;scope.querySelectorAll("input").forEach(x=>{if(x!==c){x.disabled=true;if(x.type==="radio"||x.type==="checkbox")x.checked=false;else x.value=""}})})}
form.addEventListener("change",sync);sync();
form.onsubmit=e=>{e.preventDefault();const fd=new FormData(form),data={};for(const [k,v] of fd){if(!(v instanceof File))data[k]=v}const payload={type:"auxiliary-exam",data};if(window.webkit?.messageHandlers?.saveForm)window.webkit.messageHandlers.saveForm.postMessage(payload);else if(window.Android&&typeof window.Android.saveForm==="function")window.Android.saveForm(JSON.stringify(payload));else{console.log("[AUXILIARY EXAM]",payload);history.back()}}})();
